import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.CchDE9cb.js";const f=JSON.parse('{"title":"Offline access","description":"A read-only, seven-day snapshot of the schedule for checking capacity without a connection — never a way to edit offline.","frontmatter":{"title":"Offline access","description":"A read-only, seven-day snapshot of the schedule for checking capacity without a connection — never a way to edit offline."},"headers":[],"relativePath":"guide/offline-access.md","filePath":"guide/offline-access.md","lastUpdated":null}'),i={name:"guide/offline-access.md"};function s(r,e,l,c,h,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="offline-access" tabindex="-1">Offline access <a class="header-anchor" href="#offline-access" aria-label="Permalink to &quot;Offline access&quot;">​</a></h1><p>Offline access is for reading the schedule on a train or a flaky connection, not for editing it. This page covers what it does, what it deliberately doesn&#39;t do, and how to turn it on.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Offline access is read only. While you&#39;re viewing a cached <a href="/capacitylens/reference/glossary">snapshot</a>, create, edit, delete, import and membership actions are all unavailable — CapacityLens never queues an edit to apply later, and it never tries to merge one.</p></div><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Offline access is off by default and turned on per device, not per company.</p><ol><li>Sign in on the device you want to use offline.</li><li>Open <a href="/capacitylens/guide/settings">Settings</a> and turn on <strong>Make this device available offline</strong> under <strong>Offline access</strong>.</li></ol><p>Once it&#39;s on, CapacityLens keeps a copy of the last company you opened, stored on that device only.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>The schedule, people, projects and time off exactly as they last loaded successfully while you were online.</li><li>Automatic use of that snapshot if a request can&#39;t reach the server at all — you&#39;ll see a banner explaining you&#39;re looking at cached data.</li></ul><ul><li>A snapshot that&#39;s good for seven days. After that, it&#39;s gone, and you&#39;ll need a connection to see anything.</li></ul><h2 id="what-you-don-t-get" tabindex="-1">What you don&#39;t get <a class="header-anchor" href="#what-you-don-t-get" aria-label="Permalink to &quot;What you don&#39;t get&quot;">​</a></h2><ul><li>Any way to create, edit or delete anything while offline. The moment a cached snapshot is shown, your access drops to read only for everyone, regardless of your normal role.</li><li>Edits that queue up and sync later. There&#39;s nothing to reconcile, because nothing was ever recorded. That&#39;s deliberate: you never lose work to a sync conflict, and you never discover that your &quot;saved&quot; changes went nowhere.</li><li>Offline access for a company you haven&#39;t opened before, or one you haven&#39;t opened recently enough to still be within the seven-day window.</li></ul><h2 id="when-it-refreshes" tabindex="-1">When it refreshes <a class="header-anchor" href="#when-it-refreshes" aria-label="Permalink to &quot;When it refreshes&quot;">​</a></h2><p>Every time you successfully load the schedule while online, the offline snapshot updates in the background. If the server is reachable but returns an error, or a request takes too long, CapacityLens shows a retry screen instead of silently falling back to old data — so you&#39;re never looking at a stale schedule without knowing it.</p><h2 id="turning-it-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-it-off" aria-label="Permalink to &quot;Turning it off&quot;">​</a></h2><p>Turning off <strong>Make this device available offline</strong> in Settings — or signing out — clears the cached snapshot and everything CapacityLens stored to protect it on that device. <strong>Clear device data</strong>, further down the same Settings page, does the same cleanup along with the rest of your local preferences, if you want to wipe the slate without waiting.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don&#39;t turn on offline access on a shared or borrowed device. The cached snapshot is encrypted on disk, but anyone using the browser while you&#39;re signed in can still see it through the app itself, same as any other page.</p></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/guide/settings">Settings</a> covers the rest of the switches, and <a href="/capacitylens/guide/the-schedule">The schedule</a> covers what you&#39;re actually looking at, online or off.</p>',19)])])}const p=t(i,[["render",s]]);export{f as __pageData,p as default};
